package cn.zhuatech.meetingai.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
/**
 * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
 */
@Service public class MeetingMinutesPublicationService{/**
                                                        * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                        */
public Assessment assess(Request r){List<String>b=new ArrayList<>(),a=new ArrayList<>();if(!r.participantNoticeComplete())b.add("参会者转写与 AI 使用告知未完成");if(!r.confidentialityClassified())b.add("会议保密等级未确定");if(!r.transcriptCoverageComplete())b.add("会议转写覆盖不完整");if(!r.decisionsValidated())b.add("会议决策未由责任人确认");if(!r.actionOwnersAndDueDatesComplete())b.add("行动项责任人与截止日不完整");if(!r.sensitiveContentRedacted())b.add("敏感内容未完成脱敏");if(!r.accessPolicyApplied())b.add("纪要访问权限未应用");if(r.openDecisionDisputes()>0)b.add("存在未解决的决策异议");if(!r.finalApprovalComplete())b.add("纪要发布审批未完成");if(!b.isEmpty()){a.add("阻断纪要分发并完成保密、内容和责任确认");return new Assessment(Decision.BLOCKED,b,a);}if(!r.retentionPolicyApplied()||!r.changeAuditEnabled()){if(!r.retentionPolicyApplied())a.add("应用转写和纪要保留期限");if(!r.changeAuditEnabled())a.add("启用纪要修改与重新批准审计");return new Assessment(Decision.REVIEW,b,a);}a.add("批准纪要分发并归档决策、行动项和审批记录");return new Assessment(Decision.PUBLISH,b,a);}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              */
public record Request(@NotBlank String meetingId,boolean participantNoticeComplete,boolean confidentialityClassified,boolean transcriptCoverageComplete,boolean decisionsValidated,boolean actionOwnersAndDueDatesComplete,boolean sensitiveContentRedacted,boolean accessPolicyApplied,@Min(0)int openDecisionDisputes,boolean retentionPolicyApplied,boolean changeAuditEnabled,boolean finalApprovalComplete){}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                */
public record Assessment(Decision decision,List<String>blockers,List<String>actions){}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      */
public enum Decision{PUBLISH,REVIEW,BLOCKED}}
